{"source":"#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    int n, m, k, sum = 0;
    scanf("%d %d %d", &n, &m, &k);
    long arr[m+1];
    for (int i = 0; i < m+1; i++){
        scanf("%ld", &arr[i]);
    }
    for (int i = 0; i < m; i++){
        if ((arr[i] >= arr[m]-k) && (arr[i] <= arr[m]+k)) sum++;
    }
    printf("%d\n", sum);
    return 0;
}"}
